1	#include "cli.hpp"
2	
3	namespace andes_sim {
4	namespace {
5	
6	// Try to read an option's value at args[i]. Supports both `--flag value`
7	// (consumes the next token, advancing i) and `--flag=value`.
8	//   returns  1 = matched, `out` set
9	//            0 = this token is not `flag`
10	//           -1 = matched `--flag` but no value follows
11	int match_opt(const std::vector<std::string>& args, size_t& i,
12	              const std::string& flag, std::string& out) {
13	  const std::string& a = args[i];
14	  if (a == flag) {
15	    if (i + 1 >= args.size()) return -1;
16	    out = args[++i];
17	    return 1;
18	  }
19	  const std::string pfx = flag + "=";
20	  if (a.starts_with(pfx)) {
21	    out = a.substr(pfx.size());
22	    return 1;
23	  }
24	  return 0;
25	}
26	
27	}  // namespace
28	
29	bool is_subcommand(std::string_view name) {
30	  return name == "run" || name == "list" || name == "doctor";
31	}
32	
33	Cli parse_cli(const std::vector<std::string>& args) {
34	  Cli c;
35	  if (args.empty()) return c;  // no subcommand; caller prints usage
36	
37	  // First token is the subcommand, unless it is a top-level help request.
38	  if (args[0] == "-h" || args[0] == "--help") {
39	    c.help = true;
40	    return c;
41	  }
42	
43	  // `run` is the default command: any other first token is `run`'s own
44	  // first argument (a flag or the ELF), not a subcommand.
45	  size_t first = 1;
46	  if (is_subcommand(args[0])) {
47	    c.subcommand = args[0];
48	  } else {
49	    c.subcommand = "run";
50	    first = 0;
51	  }
52	
53	  for (size_t i = first; i < args.size(); ++i) {
54	    const std::string& a = args[i];
55	
56	    if (a == "--") {  // the passthrough boundary: rest is verbatim
57	      c.has_passthrough = true;
58	      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
59	      break;
60	    }
61	    if (a == "-h" || a == "--help") {
62	      c.help = true;
63	      continue;
64	    }
65	    if (a == "--dry-run") {
66	      c.dry_run = true;
67	      continue;
68	    }
69	    if (a == "--print-memmap") {
70	      c.print_memmap = true;
71	      continue;
72	    }
73	    if (a == "--verify") {
74	      c.verify = true;
75	      continue;
76	    }
77	    if (a == "--gdb") {
78	      c.gdb = true;
79	      continue;
80	    }
81	
82	    const struct {
83	      const char* flag;
84	      std::string* out;
85	    } opts[] = {{"--mode", &c.model},
86	                {"--engine", &c.engine},
87	                {"--trigger", &c.trigger},
88	                {"--pc-start", &c.pc_start},
89	                {"--pc-end", &c.pc_end},
90	                {"--mem-size", &c.mem_size},
91	                {"--mmap-size", &c.mem_size},  // retired spelling, same knob
92	                {"--kanata", &c.kanata},
93	                {"--objdump", &c.objdump},
94	                {"--log-level", &c.log_level},
