1	// Runtime engine discovery -- the hot-plug seam.
2	//
3	// discover_engines() returns the built-in qemu descriptor plus every engine
4	// found by scanning a directory and asking each binary to self-report via
5	// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
6	// into the framework; dropping a freshly built sim_<cfg> into the scan dir
7	// makes it appear here with no andesim rebuild.
8	//
9	// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
10	// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
11	// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
12	// $QEMU_BIN_DIR.
13	#ifndef ANDESIM_ENGINE_REGISTRY_HPP
14	#define ANDESIM_ENGINE_REGISTRY_HPP
15	
16	#include <filesystem>
17	#include <string>
18	#include <vector>
19	
20	#include "engine_descriptor.hpp"
21	#include "strutil.hpp"
22	
23	namespace andes_sim {
24	
25	// Built-in functional engine ids (the qemu64/qemu32 pair). Declared once here so
26	// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
27	// agree -- a renamed literal would otherwise break find_engine() lookups only at
28	// run time.
29	inline constexpr const char* kQemuId64 = "qemu64";
30	inline constexpr const char* kQemuId32 = "qemu32";
31	
32	struct Discovery {
33	  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
34	  std::vector<std::string> warnings;       // binaries that failed to describe
35	};
36	
37	Discovery discover_engines();
38	
39	// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
40	// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
41	// QEMU_BIN_DIR) resolved env-first then from `config_file` (default: the repo
42	// config.env); empty when unset everywhere.
43	std::filesystem::path vsim_scan_dir();
44	std::filesystem::path vsim_scan_dir(const std::filesystem::path& config_file);
45	
46	// The bundled qemu descriptor (no directory scan, no --describe subprocess).
47	// discover_engines() seeds the registry with it; `run --mode fast` resolves
48	// qemu through it directly, paying none of the Verilator-engine discovery cost.
49	// builtin_qemu_arch(xlen) builds the rv64 "qemu64" (xlen=64) or rv32 "qemu32"
50	// (xlen=32, qemu-system-riscv32); builtin_qemu() is the rv64 default.
51	EngineDescriptor builtin_qemu_arch(int xlen);
52	EngineDescriptor builtin_qemu();
53	
54	// Rewrite a discovered engine's identity from the third-party simulator name to
55	// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
56	// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
57	// dedup or shown anywhere, so every downstream consumer (list / --engine /
58	// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
59	// other backend (qemu, a drop-in alioth/sid) passes through untouched.
60	inline void normalize_engine_label(EngineDescriptor& d) {
61	  if (d.type == "verilator") d.type = "vsim";
62	  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
63	  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
64	  // report it under their internal name "csr" via --describe. Speak the CLI's
65	  // vocabulary in list / doctor too, like verilator -> vsim above.
66	  for (std::string& t : d.triggers)
67	    if (t == "csr") t = "marker";
68	}
69	
70	// Select the cycle-accurate engine for `run --mode cycle` from an
71	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
72	// to the sole cycle-accurate engine -- erroring if there are none or more than
73	// one (ambiguous). With `want_id` set, that engine must exist and be
74	// cycle-accurate. Returns nullptr and sets `err` (naming the available
75	// cycle-accurate ids) on any failure; the returned pointer aliases into
76	// `engines`, so it must outlive the result.
77	inline const EngineDescriptor* resolve_accurate_engine(
78	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
79	    std::string& err) {
80	  auto is_accurate = [](const EngineDescriptor& e) {
81	    return e.kind == "cycle-accurate";
82	  };
83	  auto accurate_ids = [&] {
84	    std::vector<std::string> ids;
85	    for (const EngineDescriptor& e : engines)
86	      if (is_accurate(e)) ids.push_back(e.id);
87	    return join(ids, ", ");
88	  };
89	
90	  if (!want_id.empty()) {  // explicit --engine
91	    for (const EngineDescriptor& e : engines) {
92	      if (e.id != want_id) continue;
93	      if (is_accurate(e)) return &e;
94	      err = "engine '" + want_id + "' is " +
95	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
96	            "; a cycle-accurate engine is required";
97	      return nullptr;
98	    }
99	    std::string have = accurate_ids();
100	    err = "no engine '" + want_id + "'" +
101	          (have.empty() ? " (no cycle-accurate engines found)"
102	                        : " (cycle-accurate engines: " + have + ")");
103	    return nullptr;
104	  }
105	
106	  // No --engine: default to the sole cycle-accurate engine.
107	  const EngineDescriptor* sole = nullptr;
108	  int n = 0;
109	  for (const EngineDescriptor& e : engines)
110	    if (is_accurate(e)) { sole = &e; ++n; }
111	  if (n == 1) return sole;
112	  if (n == 0)
113	    err = "model cycle: no cycle-accurate engine found "
114	          "(point VSIM_BIN_DIR in config.env at your external vsim build/)";
115	  else
116	    err = "model cycle: multiple cycle-accurate engines; select one with "
117	          "--engine (have: " + accurate_ids() + ")";
118	  return nullptr;
119	}
120	
121	}  // namespace andes_sim
122	
123	#endif  // ANDESIM_ENGINE_REGISTRY_HPP
