#include "engine_registry.hpp"

#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>

#include <unistd.h>

#include "config_env.hpp"
#include "json.hpp"
#include "process.hpp"
#include "repo_root.hpp"

namespace fs = std::filesystem;

namespace andes_sim {

// The bundled functional engine(s). QEMU does not implement --describe, so the
// descriptor is built in. builtin_qemu_arch(64) is the rv64 "qemu64";
// builtin_qemu_arch(32) is the rv32 "qemu32" (qemu-system-riscv32). The
// standalone (model=fast) run uses qemu's OWN default -cpu -- the user's post-`--`
// args (incl. an explicit -cpu) still win; only the rv64 hybrid fast-leg pins a
// -cpu. Binary path honors $VSIM_QEMU / $VSIM_QEMU32, then $QEMU_BIN_DIR (env or
// config.env), then the legacy in-tree build. Exposed (engine_registry.hpp) so
// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
// scan whole-registry discovery would spawn.
EngineDescriptor builtin_qemu_arch(int xlen) {
  const bool rv32 = (xlen == 32);
  EngineDescriptor d;
  d.id = rv32 ? kQemuId32 : kQemuId64;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = xlen;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone"};
  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
    // (empty for marker), folded by leg_trigger_args (F9).
    d.roles.push_back("fast-leg");
    // {qemu_cpu}: the accurate engine's CPU model (from its --print-qemu-config
    // driver globals; run_plan falls back to the andes-ax45mpv family default).
    // The -readconfig globals apply only to the driver they name, so the model
    // must follow the engine -- andes-ax45mpv silently kept vlen=512 when the
    // ax66 (VLEN 128) pairing asked for 128.
    d.invoke.push_back(
        {"fast-leg",
         {"{bin}", "-object",
          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
          "{qemu_cpu},vlen={vlen}", "-nographic", "-semihosting-config",
          "enable=on,target=native", "-bios", "{elf}", "-plugin",
          "{plugin},outfile={state_out}{trigger}"}});
  }

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs the vplat fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv (rv64) / andes-a46mpv (rv32). We pass NO vlen --
  // the cpu model's own QEMU default applies, so both scalar and vector binaries
  // run out of the box; a user who needs a specific width passes it via the
  // post-`--` -cpu (e.g. -cpu andes-ax46mpv,vlen=512), which still wins.
  // run_passthrough fills {bin}/{elf}.
  const char* fast_cpu = rv32 ? "andes-a46mpv" : "andes-ax46mpv";
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", fast_cpu, "-nographic",
        "-semihosting-config", "enable=on,target=native", "-bios", "{elf}"}});

  const std::string sys =
      std::string("qemu-system-") + (rv32 ? "riscv32" : "riscv64");
  const char* env = rv32 ? "VSIM_QEMU32" : "VSIM_QEMU";
  if (const char* q = std::getenv(env); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / sys).string();
  else
    d.bin_path = (repo_root() / "build" / "qemu" / sys).string();
  return d;
}

// rv64 qemu (back-compat: the default functional engine and hybrid fast leg).
EngineDescriptor builtin_qemu() { return builtin_qemu_arch(64); }

namespace {

constexpr int kDescribeTimeoutMs = 5000;

bool is_executable_file(const fs::path& p) {
  std::error_code ec;
  if (!fs::is_regular_file(p, ec)) return false;
  return ::access(p.c_str(), X_OK) == 0;
}

std::string read_file(const fs::path& p) {
  std::ifstream f(p, std::ios::binary);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// Ask one binary to describe itself: try `<bin> --describe`, else read the
// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
// a human-readable note in `warn`.
bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
    json::Parsed p = json::parse(r.out);
    if (p.ok) {
      std::string err = descriptor_from_json(p.value, d);
      if (err.empty()) {
        d.bin_path = bin.string();
        d.source = "--describe";
        return true;
      }
      warn = bin.string() + ": --describe JSON invalid: " + err;
    } else {
      warn = bin.string() + ": --describe output is not JSON: " + p.error;
    }
  }

  fs::path sidecar = bin;
  sidecar += ".json";
  std::error_code ec;
  if (fs::exists(sidecar, ec)) {
    json::Parsed p = json::parse(read_file(sidecar));
    if (p.ok) {
      EngineDescriptor sd;
      std::string err = descriptor_from_json(p.value, sd);
      if (err.empty()) {
        sd.bin_path = bin.string();
        sd.source = "sidecar";
        d = std::move(sd);
        return true;
      }
      warn = sidecar.string() + ": invalid descriptor: " + err;
    } else {
      warn = sidecar.string() + ": not JSON: " + p.error;
    }
  }

  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
  return false;
}

// `prefix` filters candidate basenames; empty accepts any executable. The
// default VSIM_BIN_DIR scan passes "sim_"; a user-curated engines dir passes
// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
// lives in the call site, not in this engine-agnostic scanner.
void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
              std::set<std::string>& seen) {
  std::error_code ec;
  if (!fs::is_directory(dir, ec)) return;

  std::vector<fs::path> entries;
  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
  std::sort(entries.begin(), entries.end());  // stable, deterministic order

  for (const fs::path& p : entries) {
    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
    if (!is_executable_file(p)) continue;
    EngineDescriptor d;
    std::string warn;
    if (describe_one(p, d, warn)) {
      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
    } else if (!warn.empty()) {
      out.warnings.push_back(warn);
    }
  }
}

}  // namespace

// See engine_registry.hpp. VSIM_BIN_DIR (the external prebuilt vsim build,
// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
// finds the external vsim without a prior `source ./setup.sh`. Empty when
// unset everywhere -- there is no in-tree vsim to fall back to.
fs::path vsim_scan_dir(const fs::path& config_file) {
  return config_env_value("VSIM_BIN_DIR", config_file);
}

fs::path vsim_scan_dir() {
  return vsim_scan_dir(repo_root() / "config.env");
}

Discovery discover_engines() {
  Discovery out;
  std::set<std::string> seen;

  EngineDescriptor qemu = builtin_qemu();
  seen.insert(qemu.id);
  out.engines.push_back(std::move(qemu));

  // rv32 functional engine, listed alongside qemu so `list engines` shows both
  // (its binary is qemu-system-riscv32 under the same QEMU_BIN_DIR).
  EngineDescriptor qemu32 = builtin_qemu_arch(32);
  seen.insert(qemu32.id);
  out.engines.push_back(std::move(qemu32));

  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
    std::stringstream ss(env);
    std::string dir;
    while (std::getline(ss, dir, ':'))
      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
  } else {
    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
  }
  return out;
}

}  // namespace andes_sim

// The phase-plan grammar driven by run_plan (F6), minus the dropped QEMU2
// step.
//
// A Plan is a list of Steps; each Step names an engine (by id, resolved against
// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
// order, threads the drained hybrid_state_v1 file forward, and returns each
// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
// mcycle.
#ifndef ANDESIM_PLAN_HPP
#define ANDESIM_PLAN_HPP

#include <map>
#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// The ROI delimiter for a step. `kind` is marker|pc; `params` carries
// kind-specific values (e.g. enter_pc, exit_pc) that F9 maps onto trigger
// args. F6 only exercises the default marker case (no params).
struct Trigger {
  std::string kind;
  std::map<std::string, std::string> params;
};

// One leg of a plan: which engine, which invoke role, under which trigger.
// `extra_args` are verbatim tokens appended after the filled template and the
// trigger args -- the seam for user-forwarded per-leg flags (e.g. the vsim
// leg's --kanata), which are orthogonal to the trigger.
struct Step {
  std::string engine_id;  // "qemu" | "verilator:ax45mpv_premium"
  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
  Trigger trigger;
  std::vector<std::string> extra_args{};  // default-init: keeps 3-field Step{} literals warning-free
};

// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
// every leg so memory threads through.
struct Plan {
  std::string elf;          // path to the ELF every leg launches
  long long mem_size = 0;   // shared-mmap size in bytes
  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
  std::vector<Step> steps;
  // The engine whose hardware the fast leg(s) must model when the plan has
  // NO accurate-leg step of its own (the --verify oracle plan): the ISA sync
  // ({vlen}, {qemu_cpu}, -readconfig, LM sidecars) reads this engine instead.
  // Empty => derive from the plan's accurate-leg step (the normal case).
  std::string hw_engine_id;
};

// What one drain step measured (read back from its state file), plus the
// leg's captured stdout -- the guest program's own output (UART/semihosting)
// rides the engine's stdout and must flow through to the user. `st` is the
// full drained record (verify_oracle F4: run --verify diffs the vsim drain
// against the oracle leg's in-process, after run_plan removed the files).
struct PhaseResult {
  unsigned long long mcycle = 0;
  unsigned long long minstret = 0;
  std::string out;
  hybrid_state_v1 st{};
};

// Aggregate outcome. `error` empty => every step matched its expected exit and
// drained a valid state file; `phases` then holds one entry per step in order.
struct PlanResult {
  std::string error;
  std::vector<PhaseResult> phases;
  // The concrete per-step argv run_plan built (after placeholder fill, qemu_cfg
  // staging, and state threading). Populated whether or not the steps spawn, so
  // a --dry-run can print the exact commands without executing them.
  std::vector<std::vector<std::string>> argvs;
  // On a leg failure: where the kept evidence lives (the workdir's drain/
  // sidecar/cfg files, a copy of the ELF, manifest.txt). Empty on success or
  // when the bundle could not be written.
  std::string repro_dir;
  bool ok() const { return error.empty(); }
};

}  // namespace andes_sim

#endif  // ANDESIM_PLAN_HPP

// The phase-plan executor (F6) -- there is no QEMU2 handback leg.
// run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and reports each leg's mcycle/minstret.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDESIM_RUN_PLAN_HPP
#define ANDESIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"
#include "process.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
  // QEMU `-readconfig` file matching the accurate engine's ISA, distilled from
  // its config.inc (the engine's `--print-qemu-config`). Empty => the fast leg
  // keeps its descriptor's default `-cpu` (engines without the flag; FA2).
  std::string qemu_cfg;
  // The QEMU CPU model the fast leg must instantiate ({qemu_cpu} fill),
  // parsed from the same probe's `driver = "<cpu>-riscv-cpu"` globals: the
  // readconfig globals only apply to THAT driver, and a mismatched model
  // silently ignores them (found live: andes-ax45mpv kept vlen=512 when the
  // ax66 run asked for 128). Empty => the family default (andes-ax45mpv).
  std::string qemu_cpu;
};

// hw-config sync: the QEMU fast leg models the hardware the accurate-leg
// engine measures, so its -cpu vlen follows that engine's descriptor. 512 is
// the fallback for engines that report none. One definition, used by both the
// plan executor ({vlen} fill) and the hybrid banner.
inline long synced_vlen(long engine_vlen) {
  return engine_vlen > 0 ? engine_vlen : 512;
}

// A trigger's per-leg argv contribution, dispatched by the leg's role. The
// QEMU plugin takes its trigger as a comma-suffix folded INTO the one `-plugin`
// token (so it rides the `{trigger}` placeholder); vsim takes separate tokens
// appended to its argv. marker contributes nothing (plugin/vsim detect the markers
// themselves).
struct LegTriggerArgs {
  std::string plugin_suffix;        // qemu fast-leg: appended to {trigger}
  std::vector<std::string> extra;   // vsim accurate-leg: appended tokens
};

// Map `t` onto `role`'s argv contribution. marker -> empty. pc -> qemu
// `,enter_pc=<enter_pc>` / vsim `--hybrid-exit-pc <exit_pc>`. Roles other
// than fast-leg/accurate-leg get nothing. A missing required param or an
// unknown trigger kind sets `err` (and returns an empty contribution).
//
// NOTE (altitude debt): these flag spellings are framework-side per-engine
// knowledge -- the one place F9 hardcodes a fast/accurate engine's CLI, unlike
// the base argv which comes from each engine's `--describe` invoke template.
// This is a deliberate scope cut: the principled form (per-(trigger,role) argv
// templates carried in `--describe`, filled by build_argv like `invoke`) would
// extend the F2 engine contract and is left for a later feature.
LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err);

// Turn an accurate engine's `<bin> --print-qemu-config` probe into a QEMU
// `-readconfig` file under `workdir`. On a clean probe (exit 0, non-empty
// stdout) writes `workdir/qemu.cfg` and returns its path; on any failure
// (engine without the flag -> the parser throws -> non-zero exit; timeout;
// spawn failure; empty output; unwritable dir) returns "" -- the tolerant
// fallback that leaves the fast leg on its descriptor's default -cpu.
std::string stage_qemu_cfg(const std::string& workdir, const RunResult& probe);

// The QEMU CPU model named by a `--print-qemu-config` probe's text: the first
// `driver = "<cpu>-riscv-cpu"` global, stripped of the "-riscv-cpu" suffix.
// "" when the text names none (probe failed / engine without the hook) -- the
// caller falls back to the family-default -cpu.
std::string qemu_cpu_from_cfg(const std::string& cfg_text);

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

// The exit code a leg returns after draining its state and handing off (the
// driver-side mirror of vsim's kExitHandoffToQemu). Every plan step is a drain
// step, so this is the expected per-leg exit.
constexpr int kDrainRc = 200;

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = kDrainRc;   // drain success code
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
  bool dry_run = false;       // build argvs (incl. qemu_cfg) but spawn nothing
};

// Compose the "plan step N exited wrong" diagnostic. A drain step (expect_rc is
// the handoff/drain code) that exits 0 ran the ELF to completion without ever
// reaching its ROI boundary -- the marker/pc trigger never fired; say so and
// name the trigger kind so the fix (right ELF / right --trigger) is obvious.
// Any other mismatch gets the plain "expected X, got Y" line.
std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
                               int got_rc);

// Execute `plan`: resolve the plugin, acquire the shared mmap (allocate one
// under /dev/shm when plan.mmap_path is empty, and own it), spawn each leg with
// a timeout, require exit == expect_rc, and read back each leg's mcycle/minstret
// from its drained state file. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDESIM_RUN_PLAN_HPP

