109	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
110	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
111	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
112	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
113	// reports the plan, it does not run it.
114	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
115	                  const std::vector<std::string>& labels) {
116	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
117	  for (size_t i = 0; i < argvs.size(); ++i) {
118	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
119	                labels[i].c_str());
120	    std::printf("%s\n", render_argv(argvs[i]).c_str());
121	  }
122	  return 0;
123	}
