151	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
152	// then run the resolved engine standalone with `extra` (model flags the
153	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
154	// `clean_output` picks how the engine's output is presented: fast inherits the
155	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
156	// semihosting console works unchanged); cycle filters out the engine's banner +
157	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
158	// exit code propagates. The per-model engine + selection are resolved by the
159	// caller; `model` here only labels the positional diagnostics.
160	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
161	                   const char* model, const std::vector<std::string>& extra = {},
162	                   bool clean_output = false) {
163	  if (int rc = check_one_elf(cli, model)) return rc;
164	  // QEMU's -bios flag searches its data directory for relative paths rather
165	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
166	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
167	  if (elf.empty()) return 2;
168	  std::vector<std::string> args = extra;
169	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
170	  std::string err;
171	  const std::vector<std::string> argv =
172	      passthrough_argv(eng, "standalone", elf, args, err);
173	  if (!err.empty()) {
174	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
175	    return 2;
176	  }
177	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
178	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
179	  if (cli.dry_run)
180	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
181	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
182	  // wedged engine still leaves the exact command in the log.
183	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
184	           render_argv(argv).c_str());
185	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
186	}
