235	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
236	// its --jtag-port only after it has reset and halted the hart, so the debugger we
237	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
238	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
239	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
240	// single debugger slot). Returns false on timeout.
241	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
242	  constexpr int kPollMs = 50;
243	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
244	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
245	      char line[512];
246	      while (std::fgets(line, sizeof line, f)) {
247	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
248	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
249	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
250	        unsigned lport = 0, st = 0;
251	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
252	            && st == 0x0A && lport == port) {
253	          std::fclose(f);
254	          return true;
255	        }
256	      }
257	      std::fclose(f);
258	    }
259	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
260	  }
261	  return false;
262	}
263	
264	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
265	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
266	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
267	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
268	  const char* iceman = std::getenv("ICEMAN");
269	  if (!iceman || !*iceman) {
270	    std::fprintf(stderr,
271	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
272	                 "(export ICEMAN=<path to ICEman binary>)\n");
273	    return 2;
274	  }
275	  // Build vsim argv from the standalone template, appending user passthrough
276	  // and the JTAG port flag.
277	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
278	  if (elf.empty()) return 2;
279	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
280	  std::vector<std::string> vsim_pass = cli.passthrough;
281	  vsim_pass.push_back("--jtag-port");
282	  vsim_pass.push_back(jtag_port);
283	  std::string err;
284	  const std::vector<std::string> vsim_argv =
285	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
286	  if (!err.empty()) {
287	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
288	    return 2;
289	  }
290	  std::fprintf(stderr,
291	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
292	               jtag_port.c_str());
293	  if (fork_background(vsim_argv) < 0) {
294	    std::fprintf(stderr,
295	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
296	    return 1;
297	  }
298	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
299	  // Wait for the port to be LISTENing before launching the debugger (it does not
300	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
301	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
302	  // but launch anyway if it never appears.
303	  if (const int pnum = std::atoi(jtag_port.c_str());
304	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
305	    std::fprintf(stderr,
306	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
307	                 "after 20s; launching the debugger anyway\n",
308	                 jtag_port.c_str());
309	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
310	  // localhost, port 9104) instead of its default real-hardware adapter; without
311	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
312	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
313	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
314	}
315	
316	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
317	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
318	// engine's own output. Unlike fast, this must discover the Verilator build(s)
319	// to resolve the engine (explicit --engine, else the sole one).
320	int run_accurate(const Cli& cli) {
321	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
322	  // --describe subprocess per Verilator build only to fail on the argument.
323	  if (int rc = check_one_elf(cli, "cycle")) return rc;
324	  // --mem-size is validated but has nothing to size: the cycle engine always
325	  // models its full DRAM window. Say so instead of silently ignoring it.
326	  if (!cli.mem_size.empty()) {
327	    std::string se;
328	    if (parse_size(cli.mem_size, se); !se.empty()) {
329	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
330	                   se.c_str());
331	      return 2;
332	    }
333	    log_line(kLogWarn,
334	             "[andesim] --mem-size: the cycle engine models its full "
335	             "DRAM window; nothing to size");
336	  }
337	  Discovery disc = discover_engines();
338	  std::string err;
339	  const EngineDescriptor* eng =
340	      resolve_accurate_engine(disc.engines, cli.engine, err);
341	  if (!eng) {
342	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
343	    // Surface why an expected engine may be absent (failed --describe, etc.).
344	    for (const std::string& w : disc.warnings)
345	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
346	    return 2;
347	  }
348	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
349	  // vice versa) cannot run. Catch it here with a clear message instead of the
350	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
351	  // positional.
352	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
353	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
354	    return 2;
355	  }
356	  // --dry-run previews the standalone command and spawns nothing, so it takes
357	  // precedence over the interactive --gdb path (a dry run launches no debugger).
358	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
359	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
360	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
361	  // monitor/gdbstub are interactive).
362	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
363	}
364	
365	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
366	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
367	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
368	// driver's tests/e2e.sh delegation with a single window-cycle line.
369	int run_hybrid(const Cli& cli) {
370	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
371	  auto fail = [](const std::string& msg) {
372	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
373	    return 2;
374	  };
375	
376	  // --print-memmap: the map describes the run's window (engine + --mem-size),
377	  // not a workload, so the ELF is optional (when given it only adds the
378	  // fit-vs-scratch note) and the trigger machinery is skipped entirely.
379	  const bool memmap_only = cli.print_memmap;
380	  if (!memmap_only) {
381	    if (int rc = check_one_elf(cli, "hybrid")) return rc;
382	  } else if (cli.positional.size() > 1) {
383	    return fail("unexpected argument '" + cli.positional[1] + "'");
384	  }
385	
386	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
387	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
388	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
389	  std::string elf_path;
390	  if (!cli.positional.empty()) {
391	    elf_path = abs_elf(cli.positional[0], "--mode hybrid");
392	    if (elf_path.empty()) return 2;
393	  }
394	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
395	
396	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
397	  // mistake fails fast without spawning a --describe per Verilator build.
398	  std::string err;
399	  Trigger trig;
400	  std::vector<std::string> vsim_extras;
401	  if (!memmap_only) {
402	    trig = hybrid_trigger(cli, elf_path, err);
403	    if (!err.empty()) return fail(err);
404	
405	    // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
406	    // hybrid triggers; unknown returned an error above) -- exactly the entry
407	    // boundary --verify needs the oracle to arm on.
408	    vsim_extras = vsim_extra_args(cli, trig.kind, err);
409	    if (!err.empty()) return fail(err);
410	  }
411	
412	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
413	  if (!cli.mem_size.empty()) {
414	    std::string se;
415	    mem = parse_size(cli.mem_size, se);
416	    if (!se.empty()) return fail("--mem-size: " + se);
417	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
418	    // guest RAM here. The physical mmap reserves one V-scratch page above the
419	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
420	    // page. Failing now beats allocating a huge mmap file first and letting
421	    // QEMU die late.
422	    if (mem > max_program_mem_bytes())
423	      return fail("--mem-size " + cli.mem_size +
424	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
425	                  "reservation)");
426	  }
427	
428	  // L26/F3: refuse a run whose static image would extend into the reserved
429	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
430	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
431	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
432	  // scratch -> silent corruption. Derive the page's start from
433	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
434	  // `mem`, so the threshold tracks the reservation shape instead of relying on
435	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
436	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
437	  // reports it.
438	  {
439	    std::string e;
440	    const uint64_t top = elf_load_top(elf_path, e);
441	    const uint64_t scratch_gpa =
442	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
443	    if (e.empty() && top > scratch_gpa) {
444	      char msg[256];
445	      std::snprintf(msg, sizeof(msg),
446	                    "ELF static image ends at 0x%llx, overlapping the reserved "
447	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
448	                    "; raise --mem-size or shrink the image",
449	                    static_cast<unsigned long long>(top),
450	                    static_cast<unsigned long long>(scratch_gpa));
451	      return fail(msg);
452	    }
453	  }
454	
455	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
456	  // or the sole cycle-accurate engine (reusing the F8 selector).
457	  Discovery disc = discover_engines();
458	  const EngineDescriptor* acc =
459	      resolve_accurate_engine(disc.engines, cli.engine, err);
460	  if (!acc) {
461	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
462	    for (const std::string& w : disc.warnings)
463	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
464	    return 2;
465	  }
466	
467	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
468	  // cannot share architectural state with the rv64 fast leg).
469	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
470	  // ...and the ELF must match that engine width too (same guard as cycle).
471	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
472	    return fail(e);
473	
474	  if (memmap_only) {
475	    // The LM/HVM bases come from the same probe run_plan stages as the fast
476	    // leg's -readconfig, so the printed geometry IS the run's effective one.
477	    // Tolerant like stage_qemu_cfg: a probe failure only drops the LM rows
478	    // (hybrid_memmap warns).
479	    const RunResult probe =
480	        run_process({acc->bin_path, "--print-qemu-config"}, 5000);
481	    const std::string cfg =
482	        (!probe.spawn_failed && !probe.timed_out && probe.rc == 0) ? probe.out
483	                                                                   : "";
484	    std::fprintf(stderr, "[andesim] hybrid memory map: engine=%s mem-size=%s\n",
485	                 acc->id.c_str(),
486	                 fmt_size(static_cast<uint64_t>(mem)).c_str());
487	    std::fputs(render_memmap(hybrid_memmap(*acc, mem, cfg)).c_str(), stdout);
488	    // With an ELF given, say where its static image lands in that window.
489	    if (!elf_path.empty()) {
490	      std::string e;
491	      const uint64_t top = elf_load_top(elf_path, e);
492	      if (e.empty())
493	        std::printf("ELF %s: static image top 0x%llx (%s)\n",
494	                    elf.stem().string().c_str(),
495	                    static_cast<unsigned long long>(top),
496	                    top <= static_cast<uint64_t>(mem)
497	                        ? "fits DRAM"
498	                        : "OVERLAPS the reserved V-scratch page; raise "
499	                          "--mem-size");
500	    }
501	    return 0;
502	  }
503	
504	  Plan plan;
505	  plan.elf = elf_path;
506	  plan.mem_size = mem;
507	  Step qemu_step{kQemuId64, "fast-leg", trig};
508	  Step vsim_step{acc->id, "accurate-leg", trig};
509	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
510	  // #1: with no --verify the driver consumes only the vsim mcycle delta, so ask
511	  // the accurate leg to drain just the counters and skip the full register-file
512	  // readback (~190 DM abstract commands). --verify keeps the full drain so the
513	  // oracle diff sees every field. Driver policy lives here next to the rest of
514	  // the verify reasoning, not in vsim_extra_args (user-forwarded flags only).
515	  if (!cli.verify)
516	    vsim_step.extra_args.push_back("--drain-minimal");
517	  // L4: the vsim leg speaks the same --log-level scale; forward ours so one
518	  // flag tunes the whole pipeline (its stderr is relayed at <= debug).
519	  vsim_step.extra_args.push_back("--log-level");
520	  vsim_step.extra_args.push_back(std::to_string(log_threshold()));
521	  plan.steps = {qemu_step, vsim_step};
522	
523	  // Banner to stderr so the window-cycle result stands alone on stdout.
524	  // vlen is the synced value the fast leg inherits from the engine.
525	  log_line(kLogDebug,
526	           "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s",
527	           acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
528	           elf.stem().string().c_str());
529	  // L3 decision log: why THIS engine.
530	  log_line(kLogDebug, "[andesim] engine: %s (%s)", acc->id.c_str(),
531	           cli.engine.empty() ? "sole cycle-accurate engine"
532	                              : "selected by --engine");
533	
534	  PlanOptions opts;
535	  opts.dry_run = cli.dry_run;
536	  const PlanResult r = run_plan(plan, disc.engines, opts);
537	  if (!r.ok()) {
538	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
539	    if (!r.repro_dir.empty())
540	      std::fprintf(stderr,
541	                   "[andesim] repro: kept run artifacts at %s "
542	                   "(see manifest.txt)\n",
543	                   r.repro_dir.c_str());
544	    if (!log_file_path().empty())
545	      std::fprintf(stderr, "[andesim] repro: full log at %s\n",
546	                   log_file_path().c_str());
547	    return 1;
548	  }
549	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
550	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
551	  // then the vsim accurate leg -- and stop. Nothing was spawned.
552	  if (cli.dry_run) {
553	    std::vector<std::string> labels;
554	    labels.reserve(plan.steps.size());
555	    for (const Step& s : plan.steps)
556	      labels.push_back(s.role + " [" + s.engine_id + "]");
557	    return print_dry_run(r.argvs, labels);
558	  }
559	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
560	  // then anything the ROI wrote on vsim) belong to the user. The vsim
561	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
562	  // Version) -- strip it so only real program output shows, the same as `cycle`
563	  // does; its [info] log is already absent (the leg's stderr was dropped at
564	  // capture). The QEMU leg has no banner, so it relays verbatim.
565	  for (size_t i = 0; i < r.phases.size(); ++i) {
566	    const std::string& out = r.phases[i].out;
567	    if (out.empty()) continue;
568	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
569	      const std::string shown = strip_vsim_banner(out);
570	      std::fwrite(shown.data(), 1, shown.size(), stdout);
571	    } else {
572	      std::fwrite(out.data(), 1, out.size(), stdout);
573	    }
574	  }
575	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
576	  // vsim mcycle delta.
577	  {
578	    const unsigned long long q_mc = r.phases[0].mcycle;
579	    const unsigned long long v_mc = r.phases[1].mcycle;
580	    // The answer line, same shape as cycle mode; the raw mcycle operands are
581	    // debug detail.
582	    log_result(kLogInfo, "[andesim] %llu cycles", v_mc - q_mc);
583	    log_result(kLogDebug,
584	               "[andesim] window: trigger=%s vsim mcycle=%llu qemu mcycle=%llu",
585	               trig.kind.c_str(), v_mc, q_mc);
586	  }
587	
588	  // v6 incompatibility surface: the QEMU1 drain's write-mask records which
589	  // config CSRs the program actually wrote; any of them this engine does not
590	  // implement would TRAP on its silicon (the program would never reach the
591	  // ROI), yet the hybrid restore silently skipped it. Warn -- the figure may
592	  // not represent this engine running this program.
593	  {
594	    const std::string w = unsupported_written_warning(
595	        r.phases[0].st, acc->andes_csrs, acc->id);
596	    if (!w.empty() && log_on(kLogWarn)) std::fputs(w.c_str(), stderr);
597	  }
598	
599	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
600	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
601	  // halt pc, and diff the two drains in-process. The oracle plan gets its
602	  // own fresh mmap: reusing the main run's would boot the oracle on the
603	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
604	  // output was already relayed from the main run.
605	  if (cli.verify) {
606	    char pcbuf[32];
607	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
608	                  static_cast<unsigned long long>(r.phases[1].st.pc));
609	    Trigger vtrig;
610	    vtrig.kind = "verify-" + trig.kind;
611	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
612	    vtrig.params["drain_pc"] = pcbuf;
613	
614	    Plan vplan;
615	    vplan.elf = elf_path;
616	    vplan.mem_size = mem;
617	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
618	    // The oracle must model the same hardware as the main run's accurate
619	    // engine ({vlen}/{qemu_cpu}/-readconfig sync) -- without this it ran the
620	    // family-default CPU and false-diffed on vlenb (and, on an H-capable
621	    // engine, on mideleg's read-only-one delegation bits).
622	    vplan.hw_engine_id = acc->id;
623	
624	    log_line(kLogDebug,
625	             "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
626	             "exit, pc=%s)",
627	             pcbuf);
628	    const PlanResult vr = run_plan(vplan, disc.engines);
629	    if (!vr.ok()) {
630	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
631	      if (!vr.repro_dir.empty())
632	        std::fprintf(stderr,
633	                     "[andesim] repro: kept run artifacts at %s "
634	                     "(see manifest.txt)\n",
635	                     vr.repro_dir.c_str());
636	      return 1;
637	    }
638	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
639	    // engine does not implement (it never restored/re-read them; comparing
640	    // would false-diff). Mirrors the resume/drain gating in vsim.
641	    const DiffReport d =
642	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
643	    print_diff_report(d);
644	    if (!d.ok()) {
645	      std::fprintf(stderr,
646	                   "andesim run --verify: vsim drain diverges from the "
647	                   "QEMU oracle\n");
648	      return 1;
649	    }
650	    log_result(kLogInfo, "[verify] PASS: vsim drain matches the QEMU oracle");
651	  }
652	
653	  log_result(kLogDebug, "PASS: --mode hybrid --trigger %s (%s)",
654	             trig.kind.c_str(), elf.stem().string().c_str());
655	  return 0;
656	}
657	
658	}  // namespace
659	
660	int cmd_run(const Cli& cli) {
661	  if (cli.model.empty()) {
662	    std::fprintf(stderr,
663	                 "andesim run: --mode fast|cycle|hybrid is required "
664	                 "(pick the composition; see 'andesim run --help')\n");
665	    return 2;
666	  }
667	  if (!find_model(cli.model)) {
668	    std::fprintf(stderr,
669	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
670	                 cli.model.c_str());
671	    return 2;
672	  }
673	  if (!cli.gdb_port.empty() && !cli.gdb) {
674	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
675	    return 2;
676	  }
677	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
678	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
679	  if (cli.gdb && cli.model == "hybrid") {
680	    std::fprintf(stderr,
681	                 "andesim run: --gdb is not supported with --mode hybrid\n");
682	    return 2;
683	  }
684	  // --print-memmap prints the HYBRID composition's guest memory map (the
685	  // regions both engines support across the handoff); fast/cycle run one
686	  // engine's native map, which andesim does not model.
687	  if (cli.print_memmap && cli.model != "hybrid") {
688	    std::fprintf(stderr,
689	                 "andesim run: --print-memmap requires --mode hybrid (it "
690	                 "prints the hybrid-supported guest memory map)\n");
691	    return 2;
692	  }
693	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
694	  // composition has a second engine to check.
695	  if (cli.verify && cli.model != "hybrid") {
696	    std::fprintf(stderr,
697	                 "andesim run: --verify requires --mode hybrid (the %s "
698	                 "model has nothing to cross-check)\n",
699	                 cli.model.c_str());
700	    return 2;
701	  }
702	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
703	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
704	  // handoff builds itself, so there is no single "the engine" to forward to.
705	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
706	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
707	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
708	    std::fprintf(stderr,
709	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
710	                 "builds both legs' command lines; use --kanata/--objdump for "
711	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
712	    return 2;
713	  }
714	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
715	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
716	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
717	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
718	  // window), so reject instead of measuring something the user did not ask for.
719	  if (!cli.trigger.empty() && cli.model != "hybrid") {
720	    std::fprintf(stderr,
721	                 "andesim run: --trigger applies only to --mode hybrid "
722	                 "(the ROI delimiter); fast/cycle run the whole program\n");
723	    return 2;
724	  }
725	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
726	    std::fprintf(stderr,
727	                 "andesim run: --pc-end applies only to --mode hybrid "
728	                 "--trigger pc\n");
729	    return 2;
730	  }
731	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
732	    std::fprintf(stderr,
733	                 "andesim run: --pc-start applies only to --mode hybrid "
734	                 "--trigger pc\n");
735	    return 2;
736	  }
737	  if (cli.model == "fast") return run_fast(cli);
738	  if (cli.model == "cycle") return run_accurate(cli);
739	  return run_hybrid(cli);  // model validated above; only hybrid remains
740	}
741	
742	}  // namespace andes_sim
