146	    return "";
147	  const std::string path = workdir + "/qemu.cfg";
148	  std::ofstream f(path, std::ios::binary | std::ios::trunc);
149	  f.write(probe.out.data(), static_cast<std::streamsize>(probe.out.size()));
150	  if (!f) return "";
151	  return path;
