// See memmap.hpp for the region-selection rules and provenance.
#include "memmap.hpp"

#include <cstdio>
#include <cstdlib>

#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES

namespace andes_sim {
namespace {

// AE350 platform constants shared by BOTH engines (QEMU andes_ae350.c memmap
// table; vsim src/platform/memory_map.h). The print-memmap contract test
// cross-checks these against the engine's own dump.
constexpr uint64_t kSimControlBase = 0xe0080000;
constexpr uint64_t kSimControlSize = 0x1000;
constexpr uint64_t kUart2Base = 0xf0300000;
constexpr uint64_t kUart2Size = 0x100000;

// Strip one trailing '\r' (the cfg may come from a CRLF-writing engine) and
// surrounding spaces/tabs.
std::string trim(const std::string& s) {
  size_t b = s.find_first_not_of(" \t\r");
  if (b == std::string::npos) return "";
  size_t e = s.find_last_not_of(" \t\r");
  return s.substr(b, e - b + 1);
}

// `key = "value"` -> value (quotes optional); "" when the line is not `key = ...`.
std::string ini_value(const std::string& line, const char* key) {
  const std::string t = trim(line);
  const std::string pfx = std::string(key);
  if (t.compare(0, pfx.size(), pfx) != 0) return "";
  size_t i = pfx.size();
  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
  if (i >= t.size() || t[i] != '=') return "";
  ++i;
  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
  std::string v = t.substr(i);
  if (v.size() >= 2 && v.front() == '"' && v.back() == '"')
    v = v.substr(1, v.size() - 2);
  return v;
}

}  // namespace

std::map<std::string, std::string> qemu_cfg_soc_props(
    const std::string& cfg_text) {
  std::map<std::string, std::string> out;
  // Each [global] block carries driver/property/value lines (any order per
  // QEMU's -readconfig grammar; the engine emits driver first). Collect the
  // triple per block; commit it when the block ends or the text does.
  std::string drv, prop, val;
  bool have_val = false;
  auto commit = [&] {
    if (drv == "riscv.andes.ae350.soc" && !prop.empty() && have_val)
      out[prop] = val;
    drv.clear();
    prop.clear();
    val.clear();
    have_val = false;
  };
  size_t pos = 0;
  while (pos <= cfg_text.size()) {
    const size_t nl = cfg_text.find('\n', pos);
    const std::string line =
        cfg_text.substr(pos, nl == std::string::npos ? nl : nl - pos);
    const std::string t = trim(line);
    if (t == "[global]") {
      commit();
    } else if (std::string v = ini_value(line, "driver"); !v.empty()) {
      drv = v;
    } else if (std::string v = ini_value(line, "property"); !v.empty()) {
      prop = v;
    } else if (std::string v = ini_value(line, "value"); !v.empty()) {
      val = v;
      have_val = true;
    }
    if (nl == std::string::npos) break;
    pos = nl + 1;
  }
  commit();
  return out;
}

MemmapResult hybrid_memmap(const EngineDescriptor& eng, long long mem_size,
                           const std::string& qemu_cfg_text) {
  MemmapResult r;
  const uint64_t mem = static_cast<uint64_t>(mem_size);

  r.rows.push_back({"DRAM", 0, mem - 1,
                    "shared mmap; content survives the handoff"});
  r.rows.push_back({"V-scratch", mem, mem + HYBRID_V_SCRATCH_BYTES - 1,
                    "reserved by the hybrid V transport; not program-usable"});

  const auto props = qemu_cfg_soc_props(qemu_cfg_text);
  // ilm/dlm/hvm rows need BOTH a transportable size (descriptor, backdoor-
  // gated) AND the base from the engine's cfg. Sizes come from the descriptor:
  // they are the bytes the sidecar actually carries.
  auto base_of = [&](const char* key) -> const std::string* {
    auto it = props.find(key);
    return it == props.end() ? nullptr : &it->second;
  };
  bool geometry_missing = false;
  auto lm_row = [&](const char* region, const char* base_key, long size,
                    const std::string& transport) {
    if (size <= 0) return;  // engine cannot transport it -> unsupported -> omit
    const std::string* b = base_of(base_key);
    if (!b) {
      geometry_missing = true;
      return;
    }
    const uint64_t base = std::strtoull(b->c_str(), nullptr, 0);
    r.rows.push_back(
        {region, base, base + static_cast<uint64_t>(size) - 1, transport});
  };
  lm_row("ILM", "ilm_base", eng.ilm_size,
         "sidecar .ilm; DRAM overlay while milmb.IEN=1");
  lm_row("DLM", "dlm_base", eng.dlm_size,
         "sidecar .dlm; DRAM overlay while mdlmb.IEN=1");
  lm_row("HVM", "hvm_base", eng.hvm_size, "sidecar .hvm");
  if (geometry_missing)
    r.warnings.push_back(
        "engine '" + eng.id +
        "' reports transportable local memories but its --print-qemu-config "
        "gave no geometry; ILM/DLM/HVM rows omitted");

  r.rows.push_back({"SimControl/HTIF", kSimControlBase,
                    kSimControlBase + kSimControlSize - 1,
                    "device; state does not cross the handoff"});
  r.rows.push_back({"UART2", kUart2Base, kUart2Base + kUart2Size - 1,
                    "device (console); state does not cross the handoff"});
  return r;
}

std::string fmt_size(uint64_t bytes) {
  constexpr uint64_t kK = 1024, kM = kK * 1024, kG = kM * 1024;
  char buf[32];
  if (bytes >= kG && bytes % kG == 0)
    std::snprintf(buf, sizeof buf, "%lluG",
                  static_cast<unsigned long long>(bytes / kG));
  else if (bytes >= kM && bytes % kM == 0)
    std::snprintf(buf, sizeof buf, "%lluM",
                  static_cast<unsigned long long>(bytes / kM));
  else if (bytes >= kK && bytes % kK == 0)
    std::snprintf(buf, sizeof buf, "%lluK",
                  static_cast<unsigned long long>(bytes / kK));
  else
    std::snprintf(buf, sizeof buf, "%llu",
                  static_cast<unsigned long long>(bytes));
  return buf;
}

std::string render_memmap(const MemmapResult& r) {
  // Fixed-width columns sized for 64-bit hex; END is the INCLUSIVE last byte.
  std::string out;
  char line[256];
  std::snprintf(line, sizeof line, "%-16s %-12s %-12s %-7s %s\n", "REGION",
                "BASE", "END", "SIZE", "TRANSPORT");
  out += line;
  for (const MemmapRow& row : r.rows) {
    char base[24], end[24];
    std::snprintf(base, sizeof base, "0x%llx",
                  static_cast<unsigned long long>(row.base));
    std::snprintf(end, sizeof end, "0x%llx",
                  static_cast<unsigned long long>(row.end));
    std::snprintf(line, sizeof line, "%-16s %-12s %-12s %-7s %s\n",
                  row.region.c_str(), base, end,
                  fmt_size(row.end - row.base + 1).c_str(),
                  row.transport.c_str());
    out += line;
  }
  for (const std::string& w : r.warnings) out += "warning: " + w + "\n";
  return out;
}

}  // namespace andes_sim

// Shared-mmap allocation for andesim.
//
// The caller asks for `size` bytes; we resolve a backing directory over a
// tier list (first fit wins, fit = size + 256 MiB free), allocate a sparse
// file with mkstemp+truncate, and print one status line that always names
// the chosen tier -- and, when we fell past /dev/shm, why. HSIM_MMAP_DIR
// pins a single tier (hard error if it does not fit; no fallback past it).
#ifndef ANDESIM_SHM_HPP
#define ANDESIM_SHM_HPP

#include <functional>
#include <string>
#include <vector>

namespace andes_sim {

// Free-space headroom a tier must have beyond the requested size.
inline constexpr long long kMmapSafetyMargin = 256LL * 1024 * 1024;

// One backing-store candidate: the directory plus the label used in
// status/error messages ("/dev/shm", "~/.cache/andesim", "HSIM_MMAP_DIR=..").
struct MmapTier {
  std::string dir;
  std::string label;
};

// resolve_mmap_dir result: the chosen dir ("" on failure) and, when a tier
// was skipped, a human note saying which and why ("" when tiers[0] fit).
struct MmapDirChoice {
  std::string dir;
  std::string note;
};

// Parse "8G" / "512M" / "1024" / "1.5G" into a positive byte count. On success
// returns the count and leaves `err` empty; on failure returns 0 and sets `err`
// to the argparse-style message. Fractional values truncate (1.5G -> whole
// bytes).
long long parse_size(const std::string& spec, std::string& err);

// L26/F2: the physical shared mmap is one V-scratch page (HYBRID_V_SCRATCH_BYTES)
// larger than the program's --mem-size, so the V-register transport page sits
// just ABOVE the program's declared RAM. No program layout -- low stack, top-of-
// RAM stack, or a heap grown to the ceiling -- can reach a page past its own
// RAM, so the scratch can never be clobbered. The vsim side parks the scratch
// at the mmap's top page (v_scratch_gpa), which equals ram_base + program_bytes.
long long physical_mmap_bytes(long long program_bytes);

// The largest --mem-size whose physical mmap still fits the 2 GiB AE350 DRAM
// window (program_bytes + scratch page <= 2 GiB). --mem-size is capped here.
long long max_program_mem_bytes();

// First-fit resolver over `tiers`. `probe(dir)` returns the dir's free bytes,
// or -1 when it does not exist. A tier fits when probe >= size + margin.
// On success `err` is empty; when nothing fits, returns {"", ""} and `err`
// names every tier's reason plus the HSIM_MMAP_DIR hint. Pure: no env, no
// filesystem -- testable with a fake probe.
MmapDirChoice resolve_mmap_dir(
    const std::vector<MmapTier>& tiers, long long size,
    const std::function<long long(const std::string&)>& probe,
    std::string& err);

// The andesim cache root: $XDG_CACHE_HOME/andesim, else ~/.cache/andesim,
// else "" (no HOME). Shared by the mmap tier list and the repro bundles.
std::string andesim_cache_dir();

// Build the real tier list from the environment:
//   HSIM_MMAP_DIR set -> that single pinned tier;
//   else            -> /dev/shm, then $XDG_CACHE_HOME|~/.cache + /andesim
//                      (created here so the free-space probe can see it).
std::vector<MmapTier> mmap_tiers();

// WSL2 advice for `doctor`: given /proc/version contents, the repo dir, and
// the mmap tier list, return warning lines. Empty when not on WSL2. On WSL2:
// always the .wslconfig memory= hint (tmpfs is capped by the WSL VM), plus a
// drvfs warning for the repo or any tier dir under /mnt/ (slow, and
// MAP_SHARED is not coherent across the 9p boundary). Pure -- testable.
std::vector<std::string> wsl_warnings(const std::string& proc_version,
                                      const std::string& repo_dir,
                                      const std::vector<MmapTier>& tiers);

// Convert a --mem-size spec into the fast leg's plain QEMU `-m` argv:
// {"-m", "<MiB>M"}. Empty spec -> {} with no error (QEMU as-is). Malformed
// specs and sizes that are not a whole MiB (QEMU's -m granularity) return {}
// and set `err`.
std::vector<std::string> qemu_m_args(const std::string& spec, std::string& err);

// Allocate a sparse mmap file of `size` bytes in the resolved dir (mkstemp +
// truncate), print one "[hsim mmap] <size> at <dir> (free: <free>)" line
// (plus "; fallback: <why>" when /dev/shm was skipped), and return its path.
// On failure returns "" and sets `err`. Caller owns the file (unlink when
// done).
std::string allocate(long long size, std::string& err,
                     const std::string& prefix = "hsim-shm.");

}  // namespace andes_sim

#endif  // ANDESIM_SHM_HPP

