18	// token of only safe characters passes through; anything else (empty, spaces,
19	// quotes, globs) is wrapped in single quotes with embedded `'` escaped as
20	// '\''. Used by render_argv for the --dry-run command preview.
21	inline std::string shell_quote(const std::string& s) {
22	  if (!s.empty()) {
23	    bool safe = true;
24	    for (char c : s)
25	      if (!std::isalnum(static_cast<unsigned char>(c)) &&
26	          !std::strchr("_@%+=:,./-", c)) {
27	        safe = false;
28	        break;
29	      }
30	    if (safe) return s;
31	  }
32	  std::string out = "'";
33	  for (char c : s) out += (c == '\'') ? "'\\''" : std::string(1, c);
34	  out += "'";
35	  return out;
36	}
