50	// one arg) and more than once. Recognised keys come from `ctx`; a "{key}" with
51	// no matching ctx entry is an error (returns {} and sets `err`). On success
52	// `err` is cleared and the fully-resolved argv is returned.
53	std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
54	                                    const std::map<std::string, std::string>& ctx,
