// See hybrid.hpp. Builds the ROI Trigger from the CLI, resolving pc boundaries.
#include "hybrid.hpp"

#include <cstdint>

#include "elf_syms.hpp"
#include "log.hpp"

namespace andes_sim {
namespace {

// Numeric value of a bare-hex PC string from resolve_pc. resolve_pc already
// validated the digits; an absurd >64-bit address (out_of_range) yields false,
// so the equal-ROI guard simply skips it (the bogus address fails downstream).
bool hex_pc(const std::string& s, uint64_t& out) {
  try {
    std::size_t pos = 0;
    out = std::stoull(s, &pos, 16);
    return pos == s.size();
  } catch (...) {
    return false;
  }
}

}  // namespace

Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
                       std::string& err) {
  err.clear();
  // --trigger is REQUIRED for hybrid: no silent default. An absent trigger used
  // to fall back to marker, which masked running an unmarked ELF (the fast leg
  // ran to completion instead of draining at the ROI, surfacing only as a
  // cryptic "expected exit 200, got 0"). Make the user name the ROI delimiter.
  if (cli.trigger.empty()) {
    err = "--trigger marker|pc is required "
          "(the ROI delimiter; see 'andesim run --help')";
    return {};
  }
  const std::string kind = cli.trigger;

  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params

  if (kind == "pc") {
    if (cli.pc_start.empty() || cli.pc_end.empty()) {
      err = "trigger pc requires --pc-start and --pc-end "
            "(a symbol name or 0x address)";
      return {};
    }
    std::string e1, e2;
    const std::string enter = resolve_pc(elf, cli.pc_start, e1);
    if (!e1.empty()) { err = e1; return {}; }
    const std::string exit = resolve_pc(elf, cli.pc_end, e2);
    if (!e2.empty()) { err = e2; return {}; }
    // A zero-length ROI (enter == exit) is degenerate: vsim resumes at the
    // enter PC and the exit trigger fires on that very instruction, so the
    // window measures nothing. Compare numerically -- a symbol and its literal
    // 0x address (or 0x0001000 vs 0x1000) are different strings, same PC.
    uint64_t a_enter = 0, a_exit = 0;
    if (hex_pc(enter, a_enter) && hex_pc(exit, a_exit) && a_enter == a_exit) {
      err = "trigger pc: --pc-start and --pc-end resolve to the same address "
            "0x" + enter + " (an empty ROI measures nothing)";
      return {};
    }
    // L3 decision log: what the user's boundary specs resolved to.
    log_line(kLogDebug, "[andesim] trigger pc: %s -> 0x%s, %s -> 0x%s",
             cli.pc_start.c_str(), enter.c_str(), cli.pc_end.c_str(),
             exit.c_str());
    // Store with the 0x prefix the plugin (enter_pc=0x..) and vsim
    // (--hybrid-exit-pc 0x..) expect; leg_trigger_args concatenates verbatim.
    return {"pc", {{"enter_pc", "0x" + enter}, {"exit_pc", "0x" + exit}}};
  }

  err = "unknown trigger '" + kind + "' (want marker|pc)";
  return {};
}

std::string hybrid_hw_check(const EngineDescriptor& acc) {
  if (acc.xlen != 0 && acc.xlen != 64)
    return "engine " + acc.id + " is rv" + std::to_string(acc.xlen) +
           " (xlen=" + std::to_string(acc.xlen) +
           "); the hybrid fast leg (QEMU) is rv64-only";
  return "";
}

std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
                                         std::string& err) {
  err.clear();
  std::vector<std::string> out;

  // kanata ROI visualization first (marker/pc only; objdump rides kanata).
  if (!cli.kanata.empty()) {
    if (kind != "marker" && kind != "pc") {
      err = "--kanata is only supported with trigger marker or pc (got " + kind +
            ")";
      return {};
    }
    out.push_back("--kanata");
    out.push_back(cli.kanata);
    out.push_back("--kanata-roi");
    if (!cli.objdump.empty()) {
      out.push_back("--objdump");
      out.push_back(cli.objdump);
    }
  } else if (!cli.objdump.empty()) {
    err = "--objdump requires --kanata";
    return {};
  }

  return out;
}

}  // namespace andes_sim

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <functional>
#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// is redirected to /dev/null; stderr too, unless relay_stderr is set, in
// which case the child inherits OUR stderr and its diagnostics stream live
// (used to surface the legs' leveled logs at --log-level <= debug). If the
// child runs longer than timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms,
                      bool relay_stderr = false);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

// Fork a child that execs argv with inherited stdio and return immediately
// without waiting. Used by `run --mode cycle --gdb` to launch vsim in the
// background before exec-ing ICEman in the foreground. Returns the child pid
// on success, -1 on empty argv or fork failure.
int fork_background(const std::vector<std::string>& argv);

// Run argv with BOTH stdout and stderr captured (separate pipes) and stdin
// inherited, streaming each complete line to `on_line(stream, line)` as it
// arrives -- stream is 1 (stdout) or 2 (stderr), line excludes the trailing
// newline. The callback owns presentation (it decides what to write to the real
// streams), so this is the filtered counterpart to exec_passthrough: same "run
// to completion, no timeout, propagate exit code" contract, but the parent sees
// every line. A final unterminated line is delivered too. Returns the child's
// exit code, 128+signal if signalled, or -1 on spawn failure / empty argv.
int run_line_filtered(
    const std::vector<std::string>& argv,
    const std::function<void(int stream, std::string_view line)>& on_line);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP

