139	  {
140	    Cli c = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
141	    CHECK(c.error.empty());
142	    CHECK(c.pc_start.empty());
143	    CHECK(c.mem_size.empty());
144	  }
145	
146	  // kanata/objdump pass-through flags parse like the rest (space + =form).
147	  {
148	    Cli c = parse_cli({"run", "--mode", "hybrid", "--kanata", "k.txt",
149	                       "--objdump=o.txt", "prog.elf"});
150	    CHECK(c.error.empty());
151	    CHECK(c.kanata == "k.txt");
152	    CHECK(c.objdump == "o.txt");
153	  }
154	
155	  // --verify is a boolean (oracle differential verification), default off.
156	  {
157	    Cli c = parse_cli({"run", "--mode", "hybrid", "--verify", "prog.elf"});
158	    CHECK(c.error.empty());
159	    CHECK(c.verify);
160	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
161	    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
162	    CHECK(!d.verify);
163	  }
164	
165	  // --print-memmap is a boolean (print the hybrid guest memory map and
166	  // exit), default off; the ELF stays optional for it (cmd_run's rule).
167	  {
168	    Cli c = parse_cli({"run", "--mode", "hybrid", "--print-memmap"});
169	    CHECK(c.error.empty());
170	    CHECK(c.print_memmap);
171	    CHECK(c.positional.empty());
172	    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
173	    CHECK(!d.print_memmap);
174	  }
175	
176	  // --gdb is a boolean, default off; valid on fast and cycle.
177	  {
178	    Cli c = parse_cli({"run", "--mode", "fast", "--gdb", "prog.elf"});
179	    CHECK(c.error.empty());
180	    CHECK(c.gdb);
181	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
182	    Cli d = parse_cli({"run", "--mode", "cycle", "prog.elf"});
183	    CHECK(!d.gdb);
184	  }
185	
186	  // `run` is the default command: a first token that is not a known
187	  // subcommand parses exactly like `run ...` -- flag-first form.
188	  {
189	    Cli c = parse_cli({"--mode", "fast", "prog.elf"});
190	    CHECK(c.error.empty());
191	    CHECK(c.subcommand == "run");
192	    CHECK(c.model == "fast");
193	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
194	  }
195	
196	  // ... and ELF-first form.
197	  {
198	    Cli c = parse_cli({"prog.elf", "--mode", "fast"});
199	    CHECK(c.error.empty());
200	    CHECK(c.subcommand == "run");
201	    CHECK(c.model == "fast");
202	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
203	  }
