1	// Unit tests for the F6 phase-plan executor's pure core:
2	//   - build_argv  (driver/argv.hpp)     invoke-template placeholder fill
3	//   - plan_argvs  (driver/run_plan.hpp) state-file threading across steps
4	//
5	// These cover everything in run_plan EXCEPT the live spawn loop, which the
6	// integration acceptance (tests/andes_sim/test_andes_sim_f6.sh -> a real
7	// 2-step qemu+vsim run) exercises. Plain assert-and-count harness; run by that
8	// same f6 script. No QEMU2 leg exists -- handback was removed.
9	#include <filesystem>
10	#include <fstream>
11	#include <iterator>
12	#include <map>
13	#include <string>
14	#include <vector>
15	
16	#include "argv.hpp"
17	#include "engine_descriptor.hpp"
18	#include "plan.hpp"
19	#include "process.hpp"
20	#include "run_plan.hpp"
21	#include "test_check.hpp"
22	
23	using namespace andes_sim;
24	using andes_sim::test::check_eq;
25	
26	namespace {
27	
28	// The canonical drain templates (what builtin_qemu() and vsim --describe ship).
29	const std::vector<std::string> kQemuFastLeg = {
30	    "{bin}",
31	    "-object", "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
32	    "-machine", "andes_ae350,memory-backend=mem",
33	    "-cpu", "{qemu_cpu},vlen={vlen}",
34	    "-nographic",
35	    "-semihosting-config", "enable=on,target=native",
36	    "-bios", "{elf}",
37	    "-plugin", "{plugin},outfile={state_out}{trigger}",
38	};
39	
40	const std::vector<std::string> kVsimAccurateLeg = {
41	    "{bin}", "{elf}",
42	    "--resume-from-qemu", "{state_in}",
43	    "--handoff-out", "{state_out}",
44	    "--shared-mem-path", "{mmap}",
45	    "--shared-mem-size", "{mmap_size}",
46	    "--shared-mem-base", "{mmap_base}",
47	};
48	
49	EngineDescriptor fake(const std::string& id, const std::string& bin,
50	                      const std::string& role,
51	                      const std::vector<std::string>& tmpl) {
52	  EngineDescriptor d;
53	  d.id = id;
54	  d.bin_path = bin;
55	  d.invoke.push_back({role, tmpl});
56	  return d;
57	}
58	
59	}  // namespace
60	
61	int main() {
62	  // --- build_argv: every placeholder filled, including substring + repeat ---
63	  {
64	    std::string err;
65	    std::map<std::string, std::string> ctx = {
66	        {"bin", "/q"},      {"elf", "/e"},     {"plugin", "/p"},
67	        {"mmap", "/m"},     {"mmap_size", "134217728"}, {"state_out", "/s0"},
68	        {"trigger", ""},  // marker: no plugin suffix
69	        {"vlen", "512"},
70	        {"qemu_cpu", "andes-ax45mpv"},
71	    };
72	    std::vector<std::string> got = build_argv(kQemuFastLeg, ctx, err);
73	    CHECK(err.empty());
74	    check_eq(got,
75	             {"/q", "-object",
76	              "memory-backend-file,id=mem,share=on,mem-path=/m,size=134217728",
77	              "-machine", "andes_ae350,memory-backend=mem", "-cpu",
78	              "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
79	              "enable=on,target=native", "-bios", "/e", "-plugin",
80	              "/p,outfile=/s0"},
81	             "qemu");
82	  }
83	  {
84	    std::string err;
85	    std::map<std::string, std::string> ctx = {
86	        {"bin", "/v"},  {"elf", "/e"},  {"state_in", "/s0"},
87	        {"state_out", "/s1"}, {"mmap", "/m"}, {"mmap_size", "134217728"},
88	        {"mmap_base", "0x0"},
89	    };
90	    std::vector<std::string> got = build_argv(kVsimAccurateLeg, ctx, err);
91	    CHECK(err.empty());
92	    check_eq(got,
93	             {"/v", "/e", "--resume-from-qemu", "/s0", "--handoff-out", "/s1",
94	              "--shared-mem-path", "/m", "--shared-mem-size", "134217728",
95	              "--shared-mem-base", "0x0"},
96	             "vsim");
97	  }
98	  // a repeated placeholder expands every occurrence
99	  {
100	    std::string err;
101	    std::vector<std::string> got =
102	        build_argv({"a={x},b={y},a2={x}"}, {{"x", "1"}, {"y", "2"}}, err);
103	    CHECK(err.empty());
104	    check_eq(got, {"a=1,b=2,a2=1"}, "repeat");
105	  }
106	  // an unknown placeholder is an error, not a silent empty fill
107	  {
108	    std::string err;
109	    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
110	    CHECK(got.empty());
111	    CHECK(!err.empty());
112	  }
113	
114	  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
115	  std::vector<EngineDescriptor> engines = {
116	      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
117	      fake("vsim:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
118	  };
119	  Plan plan;
120	  plan.elf = "/e";
121	  plan.mem_size = 134217728;
122	  plan.steps = {
123	      {"qemu", "fast-leg", {"marker", {}}},
124	      {"vsim:test", "accurate-leg", {"marker", {}}},
125	  };
126	  RuntimeCtx rc;
127	  rc.mmap_path = "/mm";
128	  rc.mem_size = 134217728;
129	  rc.mmap_base = "0x0";
130	  rc.plugin_path = "/pl";
131	
132	  {
133	    std::string err;
134	    std::vector<std::vector<std::string>> argvs =
135	        plan_argvs(plan, engines, "/wd", rc, err);
136	    CHECK(err.empty());
137	    CHECK(argvs.size() == 2);
138	    if (argvs.size() == 2) {
139	      // step 0 (qemu): drains to state-0.bin; no state_in referenced
140	      check_eq(argvs[0],
141	               {"/qbin", "-object",
142	                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
143	                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
144	                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
145	                "enable=on,target=native", "-bios", "/e", "-plugin",
146	                "/pl,outfile=/wd/state-0.bin,log_level=2"},
147	               "step0");
148	      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
149	      check_eq(argvs[1],
150	               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
151	                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
152	                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
153	               "step1");
154	    }
155	  }
156	  // --- plan_argvs: the fast leg inherits the accurate-leg engine's vlen ---
157	  // (hw-config sync: the engine descriptor's vlen fills {vlen} in the QEMU
158	  // -cpu template; an engine that reports none falls back to 512 -- covered
159	  // by the default plan above, whose vsim:test has no vlen.)
160	  {
161	    std::vector<EngineDescriptor> engines128 = engines;
162	    engines128[1].vlen = 128;  // e.g. vsim:ax66_makatau
163	    std::string err;
164	    std::vector<std::vector<std::string>> argvs =
165	        plan_argvs(plan, engines128, "/wd", rc, err);
166	    CHECK(err.empty());
167	    CHECK(argvs.size() == 2);
168	    if (argvs.size() == 2) {
169	      bool found = false;
170	      for (const std::string& a : argvs[0])
171	        if (a == "andes-ax45mpv,vlen=128") found = true;
172	      CHECK(found);
173	    }
174	  }
175	
176	  // --- plan_argvs: LM content transport wiring (ROADMAP_ilm_dlm F3) ---
177	  // When the accurate-leg engine reports local memories (ilm_size/dlm_size,
178	  // bytes), the fast (QEMU) leg's plugin token grows the sidecar-drain args
179	  // and the vsim leg gets --ilm/--dlm pointing at the sidecars next to its
180	  // state_in. The no-LM case (sizes 0) is already locked by the exact
181	  // check_eq on step0/step1 above: no ilm/dlm token anywhere.
182	  {
183	    std::vector<EngineDescriptor> lm = engines;
184	    lm[1].ilm_size = 65536;
185	    lm[1].dlm_size = 32768;
186	    std::string err;
187	    std::vector<std::vector<std::string>> argvs =
188	        plan_argvs(plan, lm, "/wd", rc, err);
189	    CHECK(err.empty());
190	    CHECK(argvs.size() == 2);
191	    if (argvs.size() == 2) {
192	      bool plugin_has_lm = false;
193	      for (const std::string& a : argvs[0])
194	        if (a ==
195	            "/pl,outfile=/wd/state-0.bin,ilm_size=65536,dlm_size=32768,"
196	            "log_level=2")
197	          plugin_has_lm = true;
198	      CHECK(plugin_has_lm);
199	      bool has_ilm = false, has_dlm = false;
200	      for (size_t k = 0; k + 1 < argvs[1].size(); ++k) {
201	        if (argvs[1][k] == "--ilm" && argvs[1][k + 1] == "/wd/state-0.bin.ilm")
202	          has_ilm = true;
203	        if (argvs[1][k] == "--dlm" && argvs[1][k + 1] == "/wd/state-0.bin.dlm")
204	          has_dlm = true;
205	      }
206	      CHECK(has_ilm);
207	      CHECK(has_dlm);
208	    }
209	  }
210	  // ILM-only engine: each memory gates independently, no --dlm anywhere
211	  {
212	    std::vector<EngineDescriptor> lm = engines;
213	    lm[1].ilm_size = 65536;  // dlm_size stays 0
214	    std::string err;
215	    std::vector<std::vector<std::string>> argvs =
216	        plan_argvs(plan, lm, "/wd", rc, err);
217	    CHECK(err.empty());
218	    if (argvs.size() == 2) {
219	      bool plugin_has = false;
220	      for (const std::string& a : argvs[0])
221	        if (a == "/pl,outfile=/wd/state-0.bin,ilm_size=65536,log_level=2")
222	          plugin_has = true;
223	      CHECK(plugin_has);
224	      for (const std::string& a : argvs[1]) CHECK(a != "--dlm");
225	    }
226	  }
227	
228	  // --- render_argv: a shell-quoted, copy-pasteable command line ---
229	  // Safe tokens (qemu's comma/equals args, paths) pass through untouched;
230	  // empty, spaces, and quotes get POSIX single-quoting so the line is runnable.
231	  {
232	    CHECK(render_argv({"qemu", "-cpu", "andes-ax45mpv,vlen=512"}) ==
233	          "qemu -cpu andes-ax45mpv,vlen=512");
234	    CHECK(render_argv({"-object",
235	                       "memory-backend-file,id=mem,mem-path=/m,size=134217728"}) ==
236	          "-object memory-backend-file,id=mem,mem-path=/m,size=134217728");
237	    CHECK(render_argv({"-readconfig", "/tmp/a b/qemu.cfg"}) ==
238	          "-readconfig '/tmp/a b/qemu.cfg'");
239	    CHECK(render_argv({"x", ""}) == "x ''");
240	    CHECK(render_argv({"it's"}) == "'it'\\''s'");
241	  }
242	
243	  // --- stage_qemu_cfg: a clean probe writes the cfg; a failed probe falls back ---
244	  // The accurate engine's `--print-qemu-config` stdout becomes workdir/qemu.cfg;
245	  // any probe failure (engine lacks the flag -> non-zero exit, timeout, empty)
246	  // yields "" so the fast leg keeps its default -cpu.
247	  {
248	    namespace fs = std::filesystem;
249	    const fs::path dir = fs::temp_directory_path() / "andesim-fa2-stage";
250	    fs::remove_all(dir);
251	    fs::create_directories(dir);
252	
253	    RunResult ok;
254	    ok.rc = 0;
255	    ok.out = "[global]\ndriver = \"andes-ax45mpv-riscv-cpu\"\nproperty = \"v\"\n";
256	    const std::string p = stage_qemu_cfg(dir.string(), ok);
257	    CHECK(p == (dir / "qemu.cfg").string());
258	    {
259	      std::ifstream f(p);
260	      const std::string c((std::istreambuf_iterator<char>(f)),
261	                          std::istreambuf_iterator<char>());
262	      CHECK(c == ok.out);
263	    }
264	
265	    RunResult unknown_flag;  // engine without --print-qemu-config: parser throws
266	    unknown_flag.rc = 1;
267	    unknown_flag.out = "Unrecognized option: --print-qemu-config\n";
268	    CHECK(stage_qemu_cfg(dir.string(), unknown_flag).empty());
269	
270	    RunResult timed_out;
271	    timed_out.timed_out = true;
272	    CHECK(stage_qemu_cfg(dir.string(), timed_out).empty());
273	
274	    RunResult empty_out;  // exit 0 but nothing emitted -> nothing to load
275	    empty_out.rc = 0;
276	    CHECK(stage_qemu_cfg(dir.string(), empty_out).empty());
277	
278	    fs::remove_all(dir);
279	  }
280	
281	  // --- plan_argvs: the fast leg's -cpu model follows the accurate engine ---
282	  // The engine's --print-qemu-config names its CPU driver ("andes-ax66-riscv-
283	  // cpu"); the staged readconfig globals only apply to THAT driver, and e.g.
284	  // andes-ax45mpv silently keeps vlen=512 when asked for 128 (found live:
285	  // ax66 --verify FAIL on vlenb ref=0x40 got=0x10). So {qemu_cpu} is filled
286	  // from the parsed cfg; engines without the hook keep the family default.
287	  {
288	    CHECK(qemu_cpu_from_cfg("[global]\ndriver = \"andes-ax66-riscv-cpu\"\n"
289	                            "property = \"m\"\nvalue = \"on\"\n") ==
290	          "andes-ax66");
291	    CHECK(qemu_cpu_from_cfg("[global]\ndriver = \"andes-ax45mpv-riscv-cpu\"\n") ==
292	          "andes-ax45mpv");
293	    CHECK(qemu_cpu_from_cfg("").empty());                 // no cfg -> default
294	    CHECK(qemu_cpu_from_cfg("[machine]\naia = \"x\"\n").empty());  // no driver
295	
296	    std::vector<EngineDescriptor> engines_cpu = engines;
297	    engines_cpu[1].vlen = 128;
298	    RuntimeCtx rcpu = rc;
299	    rcpu.qemu_cpu = "andes-ax66";
300	    std::string err;
301	    std::vector<std::vector<std::string>> argvs =
302	        plan_argvs(plan, engines_cpu, "/wd", rcpu, err);
303	    CHECK(err.empty());
304	    CHECK(argvs.size() == 2);
305	    if (argvs.size() == 2) {
306	      bool found = false;
307	      for (const std::string& a : argvs[0])
308	        if (a == "andes-ax66,vlen=128") found = true;
309	      CHECK(found);
310	    }
311	    // no qemu_cpu (engine lacks the hook) -> the family default fills in
312	    // (the vlen sync is independent and still follows the engine's 128)
313	    RuntimeCtx rdef = rc;
314	    std::vector<std::vector<std::string>> argvs2 =
315	        plan_argvs(plan, engines_cpu, "/wd", rdef, err);
316	    CHECK(err.empty());
317	    if (argvs2.size() == 2) {
318	      bool found = false;
319	      for (const std::string& a : argvs2[0])
320	        if (a == "andes-ax45mpv,vlen=128") found = true;
321	      CHECK(found);
322	    }
323	  }
324	
325	  // --- plan_argvs: hw_engine_id syncs a plan with NO accurate leg ---
326	  // The --verify oracle plan is QEMU-only, but it must model the same
327	  // hardware as the main run's accurate engine (found live: the ax66 oracle
328	  // ran at the family default vlen=512 -> vlenb ref=0x40 vs got=0x10, and
329	  // without H -> mideleg ref=0 vs the pinned 0x1444). hw_engine_id names
330	  // that engine; the vlen (and ISA-cfg) sync reads it when no accurate-leg
331	  // step is present.
332	  {
333	    std::vector<EngineDescriptor> engines_hw = engines;
334	    engines_hw[1].vlen = 128;
335	    Plan vplan;
336	    vplan.elf = "/e";
337	    vplan.mem_size = 134217728;
338	    vplan.steps = {{"qemu", "fast-leg", {"marker", {}}}};
339	    vplan.hw_engine_id = "vsim:test";
340	    std::string err;
341	    std::vector<std::vector<std::string>> argvs =
342	        plan_argvs(vplan, engines_hw, "/wd", rc, err);
343	    CHECK(err.empty());
344	    CHECK(argvs.size() == 1);
345	    if (argvs.size() == 1) {
346	      bool found = false;
347	      for (const std::string& a : argvs[0])
348	        if (a == "andes-ax45mpv,vlen=128") found = true;
349	      CHECK(found);
350	    }
351	  }
352	
353	  // --- plan_argvs: a QEMU readconfig cfg is injected into the fast leg only ---
354	  // The engine's config.inc, distilled to a QEMU `-readconfig` cfg, makes the
355	  // QEMU producer match the accurate engine's ISA. Only the fast (QEMU) leg
356	  // gets `-readconfig <cfg>`; the vsim accurate leg never does. An empty cfg
357	  // injects nothing (fallback to the descriptor's default -cpu).
358	  {
359	    RuntimeCtx rcfg = rc;
360	    rcfg.qemu_cfg = "/wd/qemu.cfg";
361	    std::string err;
362	    std::vector<std::vector<std::string>> argvs =
363	        plan_argvs(plan, engines, "/wd", rcfg, err);
364	    CHECK(err.empty());
365	    CHECK(argvs.size() == 2);
366	    if (argvs.size() == 2) {
367	      bool fast_has = false;
368	      for (size_t k = 0; k + 1 < argvs[0].size(); ++k)
369	        if (argvs[0][k] == "-readconfig" && argvs[0][k + 1] == "/wd/qemu.cfg")
370	          fast_has = true;
371	      CHECK(fast_has);
372	      for (const std::string& a : argvs[1]) CHECK(a != "-readconfig");
373	    }
374	  }
375	  // empty qemu_cfg (the default rc) injects no -readconfig on either leg
376	  {
377	    std::string err;
378	    std::vector<std::vector<std::string>> argvs =
379	        plan_argvs(plan, engines, "/wd", rc, err);
380	    CHECK(err.empty());
381	    if (argvs.size() == 2)
382	      for (const std::vector<std::string>& a : argvs)
383	        for (const std::string& tok : a) CHECK(tok != "-readconfig");
384	  }
385	
386	  // --- leg_trigger_args: a trigger's per-role argv contribution ---
387	  {
388	    std::string err;
389	    // marker drives nothing into the argv; the plugin/vsim detect markers.
390	    LegTriggerArgs marker = leg_trigger_args({"marker", {}}, "fast-leg", err);
391	    CHECK(err.empty());
392	    CHECK(marker.plugin_suffix.empty());
393	    CHECK(marker.extra.empty());
394	
395	    // pc: qemu gets the enter_pc plugin suffix; vsim gets the exit-pc tokens.
396	    const Trigger pc = {"pc", {{"enter_pc", "0x10"}, {"exit_pc", "0x20"}}};
397	    LegTriggerArgs pf = leg_trigger_args(pc, "fast-leg", err);
398	    CHECK(err.empty());
399	    CHECK(pf.plugin_suffix == ",enter_pc=0x10");
400	    CHECK(pf.extra.empty());
401	    LegTriggerArgs pa = leg_trigger_args(pc, "accurate-leg", err);
402	    CHECK(err.empty());
403	    CHECK(pa.plugin_suffix.empty());
404	    check_eq(pa.extra, {"--hybrid-exit-pc", "0x20"}, "pc-acc");
405	
406	    // a role outside fast-leg/accurate-leg carries no trigger args
407	    LegTriggerArgs none = leg_trigger_args(pc, "standalone", err);
408	    CHECK(err.empty());
409	    CHECK(none.plugin_suffix.empty());
410	    CHECK(none.extra.empty());
411	
412	    // unknown trigger kind / missing required param are errors
413	    leg_trigger_args({"bogus", {}}, "fast-leg", err);
414	    CHECK(!err.empty());
415	    leg_trigger_args({"pc", {}}, "fast-leg", err);
416	    CHECK(!err.empty());
417	
418	    // verify oracle leg (verify_oracle F4): qemu drains at the ROI exit,
419	    // sampling at vsim's drained pc (drain_pc).
420	    const Trigger vm = {"verify-marker", {{"drain_pc", "0x100072"}}};
421	    LegTriggerArgs vmf = leg_trigger_args(vm, "fast-leg", err);
422	    CHECK(err.empty());
423	    CHECK(vmf.plugin_suffix == ",exit_marker=1,drain_pc=0x100072");
424	    CHECK(vmf.extra.empty());
425	    const Trigger vp = {"verify-pc",
426	                        {{"exit_pc", "0x20"}, {"drain_pc", "0x28"}}};
427	    LegTriggerArgs vpf = leg_trigger_args(vp, "fast-leg", err);
428	    CHECK(err.empty());
429	    CHECK(vpf.plugin_suffix == ",exit_pc=0x20,drain_pc=0x28");
430	    leg_trigger_args({"verify-marker", {}}, "fast-leg", err);
431	    CHECK(!err.empty());  // missing drain_pc
432	    leg_trigger_args({"verify-pc", {{"drain_pc", "0x28"}}}, "fast-leg", err);
433	    CHECK(!err.empty());  // missing exit_pc
434	  }
435	
436	  // --- plan_argvs: pc trigger threads enter_pc (qemu) + exit_pc (vsim) ---
437	  {
438	    Plan p = plan;
439	    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
440	    p.steps[0].trigger = pc;
441	    p.steps[1].trigger = pc;
442	    std::string err;
443	    std::vector<std::vector<std::string>> argvs =
444	        plan_argvs(p, engines, "/wd", rc, err);
445	    CHECK(err.empty());
446	    CHECK(argvs.size() == 2);
447	    if (argvs.size() == 2) {
448	      // qemu: enter_pc folded into the single -plugin token (its last arg)
449	      CHECK(argvs[0].back() ==
450	            "/pl,outfile=/wd/state-0.bin,enter_pc=0x100000,log_level=2");
451	      // vsim: --hybrid-exit-pc appended verbatim after the filled template
452	      check_eq(argvs[1],
453	               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
454	                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
455	                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0",
456	                "--hybrid-exit-pc", "0x100042"},
457	               "pc-step1");
458	    }
459	  }
460	
461	  // --- plan_argvs: Step.extra_args append AFTER trigger args (e2e.sh order) ---
462	  {
463	    Plan p = plan;
464	    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
465	    p.steps[0].trigger = pc;
466	    p.steps[1].trigger = pc;
467	    p.steps[1].extra_args = {"--kanata", "k.txt"};
468	    std::string err;
469	    std::vector<std::vector<std::string>> argvs =
470	        plan_argvs(p, engines, "/wd", rc, err);
471	    CHECK(err.empty());
472	    if (argvs.size() == 2) {
473	      const std::vector<std::string>& v = argvs[1];
474	      CHECK(v.size() >= 4);
475	      // tail order: ... --hybrid-exit-pc 0x100042 --kanata k.txt
476	      CHECK(v[v.size() - 4] == "--hybrid-exit-pc");
477	      CHECK(v[v.size() - 3] == "0x100042");
478	      CHECK(v[v.size() - 2] == "--kanata");
479	      CHECK(v.back() == "k.txt");
480	    }
481	  }
482	
483	  // unknown engine id is an error
484	  {
485	    Plan bad = plan;
486	    bad.steps[0].engine_id = "nope";
487	    std::string err;
488	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
489	    CHECK(!err.empty());
490	  }
491	  // a role the engine has no template for is an error
492	  {
493	    Plan bad = plan;
494	    bad.steps[1].role = "no-such-role";
495	    std::string err;
496	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
497	    CHECK(!err.empty());
498	  }
499	
500	  // plan_step_rc_error: a drain leg that exits 0 ran the workload to completion
501	  // without ever reaching its ROI boundary -- the trigger never fired. The
502	  // message must say so and name the trigger kind, not just the bare
503	  // "expected exit 200, got 0" the user cannot act on.
504	  {
505	    const Step s{"qemu", "fast-leg", {"marker", {}}};
506	    const std::string m = plan_step_rc_error(0, s, 200, 0);
507	    CHECK(m.find("plan step 0") != std::string::npos);
508	    CHECK(m.find("marker") != std::string::npos);
509	    CHECK(m.find("without reaching") != std::string::npos);
510	  }
511	  // a genuine non-zero failure (engine crash, not a clean completion) keeps the
512	  // bare line -- no false "trigger never fired" claim.
513	  {
514	    const Step s{"qemu", "fast-leg", {"marker", {}}};
515	    const std::string m = plan_step_rc_error(1, s, 200, 139);
516	    CHECK(m.find("expected exit 200, got 139") != std::string::npos);
517	    CHECK(m.find("without reaching") == std::string::npos);
518	  }
519	
520	  return andes_sim::test::report("plan");
521	}
522

