21	#include "test_check.hpp"
22	
23	using namespace andes_sim;
24	
25	int main(int argc, char** argv) {
26	  const std::string elf =
27	      argc > 1 ? std::string(argv[1])
28	               : (repo_root() / "tests" / "fixtures" / "handoff_roundtrip.elf")
29	                     .string();
30	
