710	int main(int argc, char** argv) {
711	  Config cfg = parse_args(argc, argv);
712	
713	  // Arch detection.
714	  if (cfg.arch == "auto") {
715	    cfg.arch = detect_arch(cfg.elf);
716	    if (cfg.arch.empty()) {
717	      fprintf(stderr, "error: cannot auto-detect arch (not RISC-V?), pass --arch\n");
718	      return 2;
719	    }
720	  }
721	
722	  // Locate QEMU binary. QEMU is integrated as an external prebuilt binary:
723	  // QEMU_BIN_DIR (config.env, exported by setup.sh) holds qemu-system-{arch}.
724	  if (cfg.qemu.empty()) {
725	    if (const char* dir = std::getenv("QEMU_BIN_DIR"); dir && *dir) {
726	      cfg.qemu = std::string(dir) + "/qemu-system-" + cfg.arch;
727	    } else {
